const https = require('https');
// Try to PATCH the service plan to 'standard' via render_update_source
// This also updates the repo/branch to ensure they're correct
function post(path, body) {
  return new Promise((resolve) => {
    const payload = JSON.stringify(body);
    const req = https.request({ hostname: 'api.ivxholding.com', path, method: 'POST', headers: { 'Authorization': 'Bearer ' + TOKEN, 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(payload) } }, res => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => { try { resolve({status: res.statusCode, ...JSON.parse(data)}); } catch(e) { resolve({status: res.statusCode, raw: data.slice(0,2000)}); } });
    });
    req.on('error', err => resolve({error: err.message}));
    req.write(payload);
    req.end();
  });
}
(async () => {
